const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Eastern Tropical Pacific
  const geometry = ee.Geometry.Rectangle({
    coords: [-180, -10, -90, 10],
    proj: 'EPSG:4326',
    geodesic: false
  });

  // 2. Define time periods
  const nov2021Start = '2021-11-01';
  const nov2021End = '2021-11-30';
  const longTermStart = '1982-11-01';
  const longTermEnd = '2020-11-30';

  // 3. Load SST data for November 2021
  const sst2021 = ee.ImageCollection('NOAA/CDO/OISST_V2')
    .filterBounds(geometry)
    .filterDate(nov2021Start, nov2021End)
    .select('sst');

  const size2021 = sst2021.size().getInfo();
  console.log(`Nov 2021 Images: ${size2021}`);

  if (size2021 === 0) {
    console.log("No data for November 2021.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Load long-term SST data for November (1982-2020)
  const sstLongTerm = ee.ImageCollection('NOAA/CDO/OISST_V2')
    .filterBounds(geometry)
    .filter(ee.Filter.calendarRange(11, 11, 'month'))
    .filterDate(longTermStart, longTermEnd)
    .select('sst');

  const sizeLongTerm = sstLongTerm.size().getInfo();
  console.log(`Long-term Nov Images (1982-2020): ${sizeLongTerm}`);

  if (sizeLongTerm === 0) {
    console.log("No long-term data for November.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate mean SST for both periods
  const mean2021 = sst2021.mean();
  const meanLongTerm = sstLongTerm.mean();

  // 6. Get statistics with pixel count validation
  const stats2021 = mean2021.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const statsLongTerm = meanLongTerm.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: geometry,
    scale: 25000,
    maxPixels: 1e9
  }).getInfo();

  const count2021 = stats2021.sst_count;
  const countLongTerm = statsLongTerm.sst_count;

  console.log(`Nov 2021 valid pixels: ${count2021}`);
  console.log(`Long-term Nov valid pixels: ${countLongTerm}`);

  if (count2021 === 0 || countLongTerm === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  const sstValue2021 = stats2021.sst_mean;
  const sstValueLongTerm = statsLongTerm.sst_mean;

  console.log(`Nov 2021 mean SST: ${sstValue2021.toFixed(2)}°C`);
  console.log(`Long-term Nov mean SST: ${sstValueLongTerm.toFixed(2)}°C`);

  // 7. Validation and final answer
  if (sstValue2021 === null || sstValue2021 === undefined || isNaN(sstValue2021) ||
      sstValueLongTerm === null || sstValueLongTerm === undefined || isNaN(sstValueLongTerm)) {
    console.log("Calculation failed - invalid SST values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (sstValue2021 < -5 || sstValue2021 > 40 || sstValueLongTerm < -5 || sstValueLongTerm > 40) {
    console.log("SST values out of valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  const difference = sstValue2021 - sstValueLongTerm;
  console.log(`Difference (2021 - Long-term): ${difference.toFixed(2)}°C`);

  if (sstValue2021 < sstValueLongTerm) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
